def rank(A):
    A = [row[:] for row in A]
    m = len(A)
    n = len(A[0])
    r = 0
    for c in range(n):
        piv = None
        for i in range(r, m):
            if A[i][c] != 0:
                piv = i
                break
        if piv is None:
            continue
        A[r], A[piv] = A[piv], A[r]
        pv = A[r][c]
        for j in range(c, n):
            A[r][j] = A[r][j] / pv
        for i in range(m):
            if i != r and A[i][c] != 0:
                f = A[i][c]
                for j in range(c, n):
                    A[i][j] = A[i][j] - f * A[r][j]
        r += 1
        if r == m:
            break
    return r

A = [[1, 1, 0, 0], [0, 0, 1, 0], [0, -1, 0, 1]]
r = rank(A)
n = 4
nullity = n - r
print(r)
print(nullity)
print(n)
